contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint newVal) public {
        require(spender != address(0));
        require(newVal != 0);
        // first: allowance is 0 -> nonzero approve must succeed and set allowance
        bool ok1 = c.approve(spender, newVal);
        uint after1 = c.allowance(address(this), spender);
        // second: allowance is newVal (nonzero) -> another nonzero approve must fail
        bool ok2 = c.approve(spender, newVal + 1);
        uint after2 = c.allowance(address(this), spender);
        // third: zero approve must always succeed and reset allowance
        bool ok3 = c.approve(spender, 0);
        uint after3 = c.allowance(address(this), spender);
        assert(ok1 && after1 == newVal && !ok2 && after2 == newVal && ok3 && after3 == 0);
    }
}

