contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, address to, uint256 v, uint256 amt) public {
        require(spender != address(0));
        require(to != address(0));
        require(v > 0 && amt > 0 && amt <= v);

        c.XBornID(); // sets balances[owner] = totalDistributed; owner is this test

        bool okApprove = c.approve(spender, v);
        uint256 fromBalBefore = c.balanceOf(address(this));
        uint256 toBalBefore = c.balanceOf(to);

        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("transferFrom(address,address,uint256)", address(this), to, amt)
        );
        bool success = ok && abi.decode(ret, (bool));

        assert(okApprove && success
            && c.balanceOf(to) == toBalBefore + amt
            && c.balanceOf(address(this)) + amt == fromBalBefore
            && c.allowance(address(this), spender) == v - amt);
    }

    receive() external payable {}
}

